const $=(s,root=document)=>root.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=v=>(v/100).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
const hours=v=>`${Number((v/60).toFixed(1)).toLocaleString('pt-BR')} h`;
const date=v=>new Date(v).toLocaleDateString('pt-BR',{day:'2-digit',month:'short'});
const paths={home:'M3 10 12 3l9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z',cube:'m12 3 9 5v9l-9 5-9-5V8Zm0 10 9-5M12 13 3 8m9 5v9M7.5 5.5l9 5',folder:'M3 7V5h7l2 3h9v12H3Z',queue:'M8 5h13M8 12h13M8 19h13M3 5h.1M3 12h.1M3 19h.1',clock:'M12 8v5l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0Z',book:'M12 5C8 2 4 3 2 4v16c4-2 7-1 10 1 3-2 6-3 10-1V4c-2-1-6-2-10 1Zm0 0v16',plus:'M12 5v14M5 12h14',arrow:'M5 12h14m-5-5 5 5-5 5',back:'M19 12H5m5-5-5 5 5 5',spark:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5Z',help:'M9 9a3 3 0 1 1 5 2c-2 1-2 2-2 3m0 3h.01M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0Z',logout:'M9 4H4v16h5m4-13 5 5-5 5m-5-5h12',check:'m5 12 4 4L19 6',pin:'M19 10c0 5-7 12-7 12S5 15 5 10a7 7 0 0 1 14 0ZM15 10a3 3 0 1 1-6 0 3 3 0 0 1 6 0Z',users:'M16 21v-3a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v3m17-7a4 4 0 0 1 3 4v3M13 6a4 4 0 1 1-8 0 4 4 0 0 1 8 0Zm4-4a4 4 0 0 1 0 8',settings:'M4 7h16M4 17h16M8 4v6m8 4v6',file:'M14 2H4v20h16V8Zm0 0v6h6M8 13h8m-8 4h6',bell:'M5 17V9a7 7 0 0 1 14 0v8l2 2H3Zm5 5h4',rocket:'M9 15c-5-8 6-12 12-12 0 6-4 17-12 12Zm0 0-5 5m2-9-4 1v5l5-1m6 2-1 4H7l1-5m6-8h.01',pencil:'m4 16 12-12 4 4L8 20l-5 1Zm9-9 4 4',close:'m6 6 12 12M6 18 18 6',wallet:'M3 7h15a3 3 0 0 1 3 3v7a3 3 0 0 1-3 3H3Zm0 0V6a2 2 0 0 1 2-2h11v3m0 9.5h.01',box:'M3 4h18v5H3Zm2 5v11h14V9m-9 4h4',card:'M2 6h20v12H2Zm0 4h20M6 15h4',user:'M20 21a8 8 0 0 0-16 0M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0Z',shield:'M12 3 4 6v6c0 5 3.5 8 8 9 4.5-1 8-4 8-9V6Z',chart:'M3 3v18h18M8 17v-3m5 3V9m5 8V5',receipt:'M5 3h14v18l-3-2-2 2-2-2-2 2-2-2-3 2Zm4 5h6m-6 4h6',chevron:'m9 6 6 6-6 6',grid:'M4 4h7v7H4zM13 4h7v7h-7zM4 13h7v7H4zM13 13h7v7h-7z',link:'M10 14a5 5 0 0 0 7 0l3-3a5 5 0 0 0-7-7l-1 1m2 5a5 5 0 0 0-7 0l-3 3a5 5 0 0 0 7 7l1-1',external:'M14 4h6v6m0-6-9 9M19 14v6H4V5h6'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.cube}"/></svg>`;
const labels={draft:'Rascunho',review:'Em avaliação',question:'Precisamos de você',approval:'Aguardando aprovação',queued:'Na fila',printing:'Em impressão',ready:'Pronto para retirar',completed:'Concluído',cancelled:'Cancelado',failed:'Impressão interrompida'};
const explanations={draft:'Sua ideia está salva. Continue quando quiser.',review:'A equipe está verificando como produzir sua criação.',question:'Responda à equipe para que seu projeto possa continuar.',approval:'O orçamento está pronto para o responsável conferir.',queued:'Tudo aprovado! Agora é aguardar sua vez.',printing:'Sua ideia está ganhando forma.',ready:'Sua criação está pronta. Combine a retirada com a equipe.',completed:'Projeto entregue. O que você gostaria de criar agora?',cancelled:'Pedido encerrado sem cobrança.',failed:'A equipe vai avaliar uma nova tentativa, sem cobrar pela falha.'};
const badge=s=>`<span class="badge ${s}">${esc(labels[s])}</span>`;
const btn=(label,action,cls='',extra='')=>`<button type="button" class="btn ${cls}" data-action="${action}" ${extra}>${label}</button>`;
const navBtn=(label,page,ico)=>`<button data-nav="${page}" class="${state.page===page?'active':''}">${icon(ico)}<span>${label}</span></button>`;
// Menu items carry their section name. In the sidebar, sections listed in navTrees become an expandable item;
// elsewhere (the mobile "Mais" sheet) every section is a plain label followed by its buttons.
const navTrees={OPERACIONAL:['Operacional','cube'],FINANCEIRO:['Financeiro','wallet'],'EDUCAÇÃO E MARKETING':['Educação e marketing','spark'],'MINHA FAMÍLIA':['Minha família','users'],'CONFIGURAÇÕES':['Configurações','settings']};
function navGroups(menu,tree=false){let html='';for(let i=0;i<menu.length;){const g=menu[i][3];let j=i;while(j<menu.length&&menu[j][3]===g)j++;const items=menu.slice(i,j),t=tree&&navTrees[g],current=items.some(m=>m[1]===state.page);
 if(t){const open=state.navOpen?.[g]??current;html+=`<div class="nav-tree ${open?'open':''}"><button type="button" class="nav-parent ${current?'current':''}" data-action="nav-toggle" data-group="${g}" aria-expanded="${open}">${icon(t[1])}<span>${t[0]}</span>${icon('chevron','chev')}</button><div class="nav-sub">${items.map(m=>navBtn(...m)).join('')}</div></div>`;}
 else html+=(g?`<div class="nav-group">${g}</div>`:'')+items.map(m=>navBtn(...m)).join('');i=j;}return html;}
const brand=`<div class="brand"><span class="brand-mark"><img src="/brand-icon.svg" alt="" width="48" height="48"></span><div>Clube Maker <b>3D</b><small class="brand-name">EMERSOL</small></div></div>`;
let state={user:null,data:null,page:'home',filter:'active',project:null,wizard:null}, busy=false, toastTimer;
async function api(path,body){const r=await fetch('/api'+path,{method:body===undefined?'GET':'POST',headers:body===undefined?{}:{'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body)});const result=await r.json();if(!r.ok)throw new Error(result.error||'Não foi possível concluir.');return result;}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4500);}
function error(e){const target=$('dialog[open] .error')||$('#main .error')||$('.auth-form .error');if(target){target.textContent=e.message;target.scrollIntoView({block:'nearest',behavior:'smooth'});}else toast(e.message);}
function modal(title,content){const d=$('#dialog');d.innerHTML=`<button class="dialog-close" data-action="close" aria-label="Fechar">${icon('close')}</button><h2>${title}</h2><div class="error" role="alert"></div>${content}`;if(!d.open)d.showModal();}
function close(){$('#dialog').close();}
const empty=(title,text,button='')=>`<div class="empty">${icon('spark')}<h3>${title}</h3><p>${text}</p>${button}</div>`;
const header=(eyebrow,title,subtitle,button='')=>`<div class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${subtitle}</p></div>${button}</div>`;
async function boot(){const staff=new URLSearchParams(location.search).get('equipe');if(staff){await renderStaffRegistration(staff);return;}const enrollment=new URLSearchParams(location.search).get('inscricao');if(enrollment){await renderEnrollment(enrollment);return;}const s=await api('/session');state.user=s.user;state.config=s.config;state.data=null;applyTheme();if(!s.user){renderAuth(s.setup);return;}await refresh();}
async function refresh({navigate=false}={}){const independent=['profile','learn','finance-dashboard','finance-club','finance-family','stock','billing','messages'].includes(state.page),jobs=[loadFeaturePage()];if(!navigate||!state.data||!independent)jobs.push(api('/dashboard').then(data=>{state.data=data;}));await Promise.all(jobs);render();}

function renderAuth(setup=false){const token=new URLSearchParams(location.search).get('convite');const register=!!token&&!setup;$('#app').innerHTML=`<div class="auth-layout"><section class="auth-story">${brand}<div class="eyebrow">UM ESPAÇO PARA DESCOBRIR</div><h1>Grandes ideias.<br>Pequenas camadas.<br>Infinitas possibilidades.</h1><p>Da primeira ideia ao objeto nas suas mãos. Vamos aprender e criar juntos?</p><img src="/art.svg" alt="Blocos tridimensionais coloridos construídos em camadas"></section><main class="auth-form" id="main"><div><div class="eyebrow">CLUBE MAKER 3D · ITUMBIARA</div><h2>${setup?'Vamos preparar o clube?':register?'Você faz parte do clube!':'Que bom ter você aqui.'}</h2><p class="muted">${setup?'Crie a conta da equipe responsável. Esse passo acontece uma única vez, no servidor local.':register?'Use seu convite para criar uma conta e começar.':'Entre para acompanhar suas ideias e descobrir o próximo passo.'}</p><form id="auth-form" class="stack" data-mode="${setup?'setup':register?'register':'login'}">${setup||register?'<label>Seu nome<input name="name" required maxlength="80" autocomplete="name" placeholder="Como podemos chamar você?"></label>':''}<label>E-mail<input name="email" type="email" required maxlength="150" autocomplete="email" placeholder="voce@exemplo.com"></label><label>Senha<input name="password" type="password" required minlength="6" maxlength="200" autocomplete="${setup||register?'new-password':'current-password'}" placeholder="${setup||register?'Pelo menos 6 caracteres':'Sua senha'}"></label>${register?preferenceFields():''}<div class="error" role="alert"></div><button class="btn" type="submit">${setup?'Preparar meu clube':register?'Criar minha conta':'Entrar no meu espaço'} ${icon('arrow')}</button></form><p class="auth-footer">${setup?'Depois, cadastre as famílias e gere seus convites na área da equipe.':'O acesso é por convite. Ainda não tem uma conta ou precisa recuperar o acesso? Fale presencialmente com a equipe do clube.'}<br><br>Emersol Engenharia e Energia Solar · Itumbiara–GO</p></div></main></div>`;}
function render(){applyTheme();const u=state.user,admin=teamUser();const group=(name,items)=>items.filter(Boolean).map(m=>[...m,name]),familyAdmin=u.role==='admin'&&u.family_id;let menu=admin?[...group('',[['Visão geral','home','home'],['Famílias','families','users']]),...group('OPERACIONAL',[['Pedidos','projects','folder'],operatorUser()&&['Produção','queue','queue'],(operatorUser()||financeUser())&&['Estoque','stock','box']]),...group('FINANCEIRO',[financeUser()&&['Painel','finance-dashboard','chart'],financeUser()&&['Lançamentos','finance-club','receipt'],financeUser()&&['Cobranças','billing','card']]),...group('EDUCAÇÃO E MARKETING',[['Aprender','learn','book'],['Vitrine do clube','gallery','grid'],operatorUser()&&['Divulgação','posts','spark'],operatorUser()&&['Convidar famílias','invitations','plus'],u.can_broadcast&&['Comunicados','messages','bell']]),...group('MINHA FAMÍLIA',[u.family_id&&['Minha cota','balance','clock'],familyAdmin&&['Financeiro da família','finance-family','wallet']]),...group('CONFIGURAÇÕES',[adminUser()&&['Equipe','team','shield'],adminUser()&&['Configurações do clube','settings','settings'],['Meu perfil','profile','user']])]:[...group('',[['Início','home','home']]),...group('CRIAR',[['Meus projetos','projects','folder'],['Fila do clube','queue','queue']]),...group('MINHA FAMÍLIA',[['Minha cota','balance','clock'],u.role==='guardian'&&['Minha família','my-family','users'],['Financeiro da família','finance-family','wallet'],u.role==='guardian'&&['Cobranças','billing','card']]),...group('DESCOBRIR',[['Vitrine do clube','gallery','grid'],['Aprender','learn','book'],['Quero que postem','posts','spark']]),...group('CONTA',[['Meu perfil','profile','user']])];state.menu=menu;
$('#app').innerHTML=`<div class="shell"><aside class="sidebar">${brand}<div class="nav-label">${admin?'ESPAÇO DA EQUIPE':'SEU ESPAÇO DE CRIAÇÃO'}</div><nav class="nav" aria-label="Principal">${navGroups(menu,admin)}${admin?menu.filter(m=>['projects','queue'].includes(m[1])).map(m=>navBtn(...m).replace('<button ','<button data-mobile-only ')).join(''):''}<button class="mobile-more" data-action="more-menu">${icon('plus')}<span>Mais</span></button></nav><div class="sidebar-bottom"><div class="help-box">${icon('help')} <strong>Vamos aprender juntos?</strong><p>Não precisa saber tudo para começar. A gente ajuda você.</p><button data-action="help">Como o clube funciona ${icon('arrow')}</button></div><div class="profile">${avatarHtml(u)}<div><strong>${esc(u.name)}</strong><small>${admin?'Equipe do clube':u.role==='guardian'?'Responsável da família':'Participante aprendiz'}</small></div><button class="logout" data-action="logout" aria-label="Sair da conta">${icon('logout')}</button></div></div></aside><div class="content"><header class="topbar"><div class="mobile-brand">${brand}</div><span class="location">${icon('pin')} Emersol · Itumbiara, GO</span><div class="row"><span class="pill"><span class="dot"></span> ${admin?'Área da equipe':esc(state.data.family?.name||'Minha família')}</span><button data-action="account" aria-label="Minha conta">${icon('users')}</button></div></header><main class="main" id="main" tabindex="-1"><div class="error" role="alert"></div>${state.data.balance&&state.page!=='home'&&state.page!=='balance'?`<button class="quota-strip ${state.data.balance.extraMinutes>0?'over-budget':''}" data-nav="balance">${icon('clock')} ${hours(state.data.balance.available)} livres · Extras ${money(state.data.balance.extraCost)} · Filamento ${money(state.data.balance.materialCost)} ${icon('arrow')}</button>`:''}${pageContent()}<footer class="footer"><span>Clube Maker 3D Emersol · Criatividade que ganha forma.</span><span>Imagine. Crie. Imprima.</span></footer></main></div></div>`;}
function pageContent(){const feature=featurePage();if(feature!==null)return feature;switch(state.page){case'home':return teamUser()?adminHome():home();case'projects':return projectsPage();case'new':return wizardPage();case'project':return projectPage();case'queue':return queuePage();case'balance':return balancePage();case'learn':return learnPage();case'families':return familiesPage();case'settings':return settingsPage();default:return home();}}
// Pieces chosen on model sites. The club keeps the link; the team downloads the file from the site when printing.
const modelSites=[['MakerWorld','https://makerworld.com/pt'],['Printables','https://www.printables.com'],['Thingiverse','https://www.thingiverse.com']];
const siteNames={makerworld:'MakerWorld',printables:'Printables',thingiverse:'Thingiverse',cults3d:'Cults3D',thangs:'Thangs'};
const siteLabel=(site,url)=>{if(siteNames[site])return siteNames[site];try{return new URL(url).hostname.replace(/^www\./,'');}catch{return 'site da peça';}};
const licensePending=m=>m.license_level!=='open'&&!m.license_checked_at;
const licenseChip=(license,level)=>`<span class="license-chip ${level==='open'?'open':'warn'}">${icon(level==='open'?'check':'help')}${esc(license||'Licença não informada')}</span>`;
const modelThumb=src=>src?`<img class="model-thumb" src="${esc(src)}" alt="" loading="lazy">`:`<div class="model-thumb blank">${icon('cube')}</div>`;
function linkPreviewHtml(l){return `<div class="model-preview">${modelThumb(l.image)}<div><span class="eyebrow">${esc(l.siteName)}${l.profileId?' · perfil de impressão escolhido':''}</span>${l.found?`<strong>${esc(l.title)}</strong>${l.author?`<small>por ${esc(l.author)}</small>`:''}${licenseChip(l.license,l.licenseLevel)}`:`<p>${l.supported?'Não conseguimos ler os dados da peça agora.':'Este site não deixa o clube ler os dados da peça.'} Sem problema: escreva o nome da peça abaixo.</p>`}</div></div>`;}
function modelCard(p){const m=p.model;if(!m)return '';const name=siteLabel(m.site,m.url),pending=operatorUser()&&licensePending(m);
 return `<div class="card model-card"><div class="model-preview">${modelThumb(Number(m.has_image)?`/api/model-image/${p.id}`:null)}<div><span class="eyebrow">PEÇA ESCOLHIDA · ${esc(name.toUpperCase())}</span><h2>${esc(m.title)}</h2>${m.author?`<small>por ${esc(m.author)}</small>`:''}</div></div><a class="btn" href="${esc(m.url)}" target="_blank" rel="noopener noreferrer">Abrir no ${esc(name)} ${icon('external')}</a>${m.profile_id?`<p class="field-help">O link abre no perfil de impressão escolhido pela família (#${esc(m.profile_id)}).</p>`:''}<div class="summary"><div><span>Licença</span><strong>${esc(m.license||'Não informada pelo site')}</strong></div></div>${pending?`<div class="notice license-notice">${icon('help')}<div><h3>Confira a licença antes do orçamento</h3><p>${m.license_level==='restricted'?'Esta licença pode proibir uso comercial. Como o clube cobra mensalidade e material, confirme no site que a impressão é permitida.':'O site não informou a licença. Abra a peça e confira se a impressão é permitida para o clube.'}</p>${['draft','review','question','approval','failed'].includes(p.status)?btn('Marcar licença como conferida','license-dialog','secondary small'):''}</div></div>`:''}${m.license_checked_at?`<p class="field-help">Licença conferida por ${esc(m.license_checked_name||'equipe')} em ${new Date(m.license_checked_at).toLocaleDateString('pt-BR')}.</p>`:''}<p class="field-help">O arquivo não fica guardado no clube: a equipe baixa do site original na hora de imprimir.</p></div>`;}
function projectCard(p,index=0){return `<button class="card project-card" data-project="${p.id}"><div class="project-art ${['','blue','peach'][index%3]}">${Number(p.model_image)?`<img src="/api/model-image/${p.id}" alt="" loading="lazy">`:icon(p.kind==='idea'?'rocket':p.kind==='link'?'link':'cube')}</div><div class="project-body">${badge(p.status)}<h3>${esc(p.name)}</h3><p>${esc(p.participant)}${p.family_name?' · '+esc(p.family_name):''}</p><div class="project-foot"><span>${p.minutes?hours(p.minutes)+' estimadas':'Uma nova ideia'}</span><span>Ver projeto ${icon('arrow')}</span></div></div></button>`;}
function balanceCard(){return batteryHtml(state.data.balance);}
function home(){const d=state.data,attention=d.projects.find(p=>['approval','question','ready'].includes(p.status)),active=d.projects.filter(p=>!['completed','cancelled'].includes(p.status)).slice(0,3);return `${header('SEU ATELIÊ DE POSSIBILIDADES',`Olá, ${esc(state.user.name.split(' ')[0])}!`,'O que vamos tirar da imaginação hoje?',btn(icon('plus')+' Criar projeto','new'))}<section class="hero"><div class="hero-copy"><div class="eyebrow">A PRÓXIMA CRIAÇÃO COMEÇA COM VOCÊ</div><h2>Uma ideia na cabeça.<br>Um mundo nas mãos.</h2><p>Não precisa ter experiência. Traga sua curiosidade e a gente ajuda com o resto.</p>${btn('Vamos criar juntos '+icon('arrow'),'new','lime')}</div><img src="/art.svg" alt="Foguete colorido do Clube Maker 3D Emersol"></section>${attention?`<div class="notice">${icon('bell')}<div><h3>${attention.status==='approval'?'Uma ideia pronta para o próximo passo!':esc(labels[attention.status])}</h3><p>${esc(attention.name)} · ${esc(explanations[attention.status])}</p></div>${btn('Ver projeto '+icon('arrow'),'open','secondary small',`data-id="${attention.id}"`)}</div>`:''}<div class="grid two section"><section><div class="section-head"><h2>Suas ideias ganhando forma</h2><button class="text-btn" data-nav="projects">Ver todas ${icon('arrow')}</button></div>${active.length?`<div class="grid three">${active.map(projectCard).join('')}</div>`:empty('Tudo começa com uma ideia','Um brinquedo, um presente ou algo útil para a sua casa. O que você gostaria de criar?',btn(icon('plus')+' Meu primeiro projeto','new'))}<div class="section card"><div class="eyebrow">DO IMAGINAR AO FAZER</div><div class="row spread"><div><h3>Um passo de cada vez.</h3><p>Você imagina. A equipe orienta. Juntos, fazemos acontecer.</p></div><button class="text-btn" data-action="help">Conhecer o caminho ${icon('arrow')}</button></div></div></section><aside class="stack">${balanceCard()}<div class="card"><div class="section-head"><h3>Pequenas descobertas</h3>${icon('book')}</div>${lessons.slice(0,2).map((l,i)=>`<div class="learn-preview"><span class="learn-number">0${i+1}</span><div><h3>${l.title}</h3><p>${l.time} min de descoberta</p></div><button data-lesson="${i}" aria-label="Ler ${l.title}">${icon('arrow')}</button></div>`).join('')}</div></aside></div>`;}
function adminHome(){const ps=state.data.projects;const count=s=>ps.filter(p=>s.includes(p.status)).length;const action=ps.filter(p=>['review','failed','question','ready'].includes(p.status));return `${header('VAMOS FAZER ACONTECER','Um clube cheio de possibilidades.','Organize os pedidos e acompanhe cada nova descoberta.',state.user.family_id?btn(icon('plus')+' Criar projeto da família','new'):'')}${state.data.balance?batteryHtml(state.data.balance):''}<div class="grid three"><div class="card"><span class="muted">Para avaliar</span><strong class="stat">${count(['review','failed'])}</strong><button class="text-btn" data-nav="projects">Abrir pedidos ${icon('arrow')}</button></div><div class="card"><span class="muted">Na produção</span><strong class="stat">${count(['queued','printing'])}</strong><button class="text-btn" data-nav="queue">Organizar produção ${icon('arrow')}</button></div><div class="card"><span class="muted">Famílias no clube</span><strong class="stat">${state.data.families.length} <small>/ 10</small></strong><button class="text-btn" data-nav="families">Gerenciar famílias ${icon('arrow')}</button></div></div><div class="section"><div class="section-head"><h2>Precisam da sua atenção</h2><button class="text-btn" data-nav="projects">Todos os pedidos ${icon('arrow')}</button></div>${action.length?projectTable(action):empty('Tudo em dia por aqui','Cadastre uma família e gere um convite para começar a receber ideias.',btn('Cadastrar família','family-new'))}</div><div class="card section"><div class="eyebrow">OPERAÇÃO SUPERVISIONADA</div><h2>Primeiro a conferência. Depois, a impressão.</h2><p>A fila segue a ordem de aprovação. Confira a máquina e inicie a impressão no equipamento antes de atualizar a etapa no portal. O portal não aciona a impressora.</p><button class="text-btn" data-action="rules">Consultar as regras do piloto ${icon('arrow')}</button></div>`;}
function projectTable(ps){return `<div class="card table-wrap"><table><thead><tr><th>Projeto</th><th>Família / participante</th><th>Etapa</th><th>Atualizado</th><th></th></tr></thead><tbody>${ps.map(p=>`<tr><td><div class="row-model">${p.model_site?modelThumb(Number(p.model_image)?`/api/model-image/${p.id}`:null):''}<div><strong>${esc(p.name)}</strong><br><small>#${String(p.id).padStart(3,'0')}${p.model_site?' · '+esc(siteNames[p.model_site]||'Link externo'):''}</small>${p.model_site&&licensePending(p)&&!['completed','cancelled'].includes(p.status)?'<br><span class="license-chip warn">Licença a conferir</span>':''}</div></div></td><td>${esc(p.family_name||p.participant)}</td><td>${badge(p.status)}</td><td>${date(p.updated)}</td><td><button class="text-btn" data-project="${p.id}">Abrir ${icon('arrow')}</button></td></tr>`).join('')}</tbody></table></div>`;}
function projectsPage(){let ps=state.data.projects;if(state.filter==='active')ps=ps.filter(p=>!['completed','cancelled'].includes(p.status));if(state.filter==='completed')ps=ps.filter(p=>['completed','cancelled'].includes(p.status));return `${header('IDEIAS, HISTÓRIAS E DESCOBERTAS',teamUser()?'Pedidos do clube':'Meus projetos','Cada criação tem seu próprio caminho.',!teamUser()?btn(icon('plus')+' Criar projeto','new'):'')}<div class="filters" aria-label="Filtrar projetos">${[['active','Em andamento'],['completed','Finalizados'],['all','Todos']].map(([v,l])=>`<button data-filter="${v}" class="${state.filter===v?'selected':''}" aria-pressed="${state.filter===v}">${l}</button>`).join('')}</div>${ps.length?(teamUser()?projectTable(ps):`<div class="grid three">${ps.map(projectCard).join('')}</div>`):empty('Nenhum projeto nesta lista','Quando uma ideia chegar por aqui, você poderá acompanhar cada etapa.')}`;}
function newWizard(){state.wizard={step:0,kind:'idea',name:'',description:'',participant:state.data.participants.find(p=>p.active!==0)?.name||state.user.name,size:'Quero ajuda',color:'Quero ajuda',quantity:1,file:null,url:'',link:null,linkTitle:''};state.page='new';render();}
async function previewLink(){captureWizard();const w=state.wizard;if(!w.url?.trim())throw new Error('Cole o link da peça.');const r=await api('/model-links/preview',{url:w.url});w.link={...r,input:w.url.trim()};if(r.title)w.linkTitle=r.title.slice(0,200);render();}
function captureWizard(){const form=$('#wizard-form');if(!form)return;const fd=new FormData(form);for(const [key,value]of fd)if(key!=='attachment')state.wizard[key]=key==='quantity'?Number(value):value;const file=$('[name=attachment]',form)?.files[0];if(file)state.wizard.file=file;}
function wizardPage(){const w=state.wizard;if(!w)return '';const colors=[...new Set(state.data.config.materials.filter(m=>m.active).flatMap(m=>m.colors))];let content='';if(w.step===0)content=`<h2>Como você quer começar?</h2><p class="muted">Ter uma ideia já é um ótimo começo.</p><div class="grid choices"><button type="button" class="choice ${w.kind==='idea'?'selected':''}" data-kind="idea">${icon('spark')}<strong>Tenho uma ideia</strong><p>Conte o que você imaginou. A equipe ajuda a descobrir como fazer.</p></button><button type="button" class="choice ${w.kind==='file'?'selected':''}" data-kind="file">${icon('cube')}<strong>Já tenho um arquivo 3D</strong><p>Envie seu modelo em STL ou 3MF para a equipe avaliar.</p></button><button type="button" class="choice ${w.kind==='link'?'selected':''}" data-kind="link">${icon('link')}<strong>Escolhi uma peça na internet</strong><p>Cole o link de um site como MakerWorld, Printables ou Thingiverse.</p></button></div>`;
if(w.step===1&&w.kind==='link')content=`<h2>Qual peça você escolheu?</h2><p class="muted">${w.galleryItem?'Confira a peça e conte para quem ela é.':'Encontre a peça em um site de modelos 3D, copie o link da página dela e cole aqui.'}</p>${w.galleryItem?`<div class="notice">${icon('check')}<div><h3>Igual à peça da vitrine</h3><p>A equipe já imprimiu esta peça. Escolha para quem é e, na próxima etapa, a cor.</p></div></div>${linkPreviewHtml(w.link)}<div class="stack">`:`<div class="site-links">${modelSites.map(([n,u])=>`<a class="btn secondary small" href="${u}" target="_blank" rel="noopener noreferrer">${n} ${icon('external')}</a>`).join('')}</div><div class="stack"><label>Link da peça<input name="url" type="url" inputmode="url" autocomplete="off" value="${esc(w.url)}" required maxlength="600" placeholder="https://makerworld.com/pt/models/…"><span class="field-help">Vale qualquer site de modelos 3D. No MakerWorld, escolha o perfil de impressão antes de copiar o link.</span></label><div>${btn('Buscar dados da peça','link-preview','secondary small')}</div>${w.link?linkPreviewHtml(w.link)+`<label>Nome da peça<input name="linkTitle" value="${esc(w.linkTitle)}" required maxlength="200" placeholder="Ex.: caixa organizadora com tampa"></label>`:''}`}<label>Para que você quer a peça? (opcional)<textarea name="description" maxlength="3000" placeholder="Ex.: para organizar os lápis da escrivaninha.">${esc(w.description)}</textarea></label><label>Quem está pedindo?<input name="participant" value="${esc(w.participant)}" required maxlength="80" list="participants"><datalist id="participants">${state.data.participants.filter(p=>p.active!==0).map(p=>`<option value="${esc(p.name)}">`).join('')}</datalist></label></div>`;else
if(w.step===1)content=`<h2>Conte sua ideia para a gente.</h2><p class="muted">Não precisa ser perfeito. Estamos aqui para ajudar.</p><div class="stack"><label>Nome do projeto<input name="name" value="${esc(w.name)}" required maxlength="100" placeholder="Ex.: um porta-lápis em formato de foguete"></label><label>O que você quer criar?<textarea name="description" required maxlength="3000" placeholder="Como é sua ideia? Para que você quer usar a peça?">${esc(w.description)}</textarea></label><label>Quem está criando?<input name="participant" value="${esc(w.participant)}" required maxlength="80" list="participants"><datalist id="participants">${state.data.participants.filter(p=>p.active!==0).map(p=>`<option value="${esc(p.name)}">`).join('')}</datalist></label><label>${w.kind==='file'?'Arquivo do modelo 3D':'Foto ou desenho da ideia (opcional)'}<input name="attachment" type="file" accept="${w.kind==='file'?'.stl,.3mf':'.png,.jpg,.jpeg'}"><span class="field-help">${w.file?'Selecionado: '+esc(w.file.name)+' · ':''}Até 10 MB. ${w.kind==='file'?'Formatos STL e 3MF.':'Formatos PNG e JPG.'}</span></label></div>`;
if(w.step===2)content=`<h2>Como você imagina sua peça?</h2><p class="muted">Ainda não sabe? Tudo bem. Escolha “Quero ajuda”.</p><div class="stack"><label>Tamanho aproximado<select name="size">${[...(w.kind==='link'?['Como no modelo original']:[]),'Quero ajuda','Pequeno — cabe na palma da mão','Médio — até 15 cm','Grande — avaliar com a equipe'].map(s=>`<option ${w.size===s?'selected':''}>${s}</option>`).join('')}</select></label><div class="form-grid"><label>Preferência de cor<select name="color">${['Quero ajuda',...colors].map(s=>`<option ${w.color===s?'selected':''}>${esc(s)}</option>`).join('')}</select></label><label>Quantidade<input name="quantity" type="number" min="1" max="50" required value="${w.quantity}"></label></div><div class="notice">${icon('help')}<div><h3>Pequenas escolhas, grandes diferenças</h3><p>O tamanho e a quantidade mudam o tempo e o material necessário. A equipe explicará tudo no orçamento.</p></div></div></div>`;
if(w.step===3)content=`<h2>Sua ideia está pronta para sair do papel.</h2><p class="muted">Confira os detalhes antes de enviar.</p><div class="summary"><div><span>Projeto</span><strong>${esc(w.name)}</strong></div><div><span>Criador</span><strong>${esc(w.participant)}</strong></div><div><span>Tamanho</span><strong>${esc(w.size)}</strong></div><div><span>Cor e quantidade</span><strong>${esc(w.color)} · ${w.quantity} peça(s)</strong></div>${w.kind==='link'?`<div><span>Peça escolhida</span><strong>${esc(w.linkTitle)} · ${esc(w.link?.siteName||'')}</strong></div>`:`<div><span>Arquivo</span><strong>${esc(w.file?.name||'Sem arquivo')}</strong></div>`}</div><p class="preserve">${esc(w.description)}</p><div class="notice">${icon('check')}<div><h3>Sem cobrança ao enviar</h3><p>Primeiro, a equipe avalia a ideia e prepara um orçamento. Só o responsável pode aprovar os custos.</p></div></div>`;
return `<div class="wizard">${header('DA IMAGINAÇÃO PARA O MUNDO','Vamos criar algo novo?','Uma etapa de cada vez, do seu jeito.')}<div class="steps">${['Começar','Sua ideia','Detalhes','Revisar'].map((s,i)=>`<div class="step ${i===w.step?'current':''}" ${i===w.step?'aria-current="step"':''}><span>${i+1}</span>${s}</div>`).join('')}</div><form id="wizard-form" class="card">${content}<div class="error" role="alert"></div><div class="wizard-controls">${w.step?btn(icon('back')+' Voltar','wizard-back','secondary'):btn('Sair','wizard-exit','secondary')}<div class="right">${w.step>0?btn('Salvar rascunho','draft','secondary'):''}${w.step===3?'<button type="submit" class="btn">Enviar para avaliação '+icon('arrow')+'</button>':'<button type="submit" class="btn">Continuar '+icon('arrow')+'</button>'}</div></div></form></div>`;}
async function saveWizard(submit){captureWizard();const w=state.wizard;if(w.kind==='link'){if(!w.link||!w.linkTitle.trim())throw new Error('Cole o link da peça e confira o nome dela antes de salvar.');w.name=w.linkTitle.trim().slice(0,100);}if(!w.name.trim()||(w.kind!=='link'&&!w.description.trim())||!w.participant.trim())throw new Error('Preencha nome, descrição e participante antes de salvar.');if(submit&&w.kind==='file'&&!w.file)throw new Error('Adicione um arquivo STL ou 3MF.');if(w.file?.size>10*1024*1024)throw new Error('O arquivo deve ter no máximo 10 MB.');const {file,link,...fields}=w,result=await api('/projects',{...fields,link:link?{url:link.url,title:w.linkTitle}:undefined});if(w.file){try{await upload(result.id,w.file);}catch(e){state.wizard=null;await openProject(result.id);throw new Error('O rascunho foi salvo, mas o arquivo não foi enviado: '+e.message);}}if(submit)await api(`/projects/${result.id}/submit`,{});state.wizard=null;toast(submit?'Ideia enviada! A equipe vai avaliar seu projeto.':'Rascunho salvo. Continue quando quiser.');await openProject(result.id);}
async function upload(id,file){if(file.size>10*1024*1024)throw new Error('O arquivo deve ter no máximo 10 MB.');const encoded=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result.split(',')[1]);reader.onerror=()=>reject(new Error('Não foi possível ler o arquivo.'));reader.readAsDataURL(file);});return api(`/projects/${id}/file`,{name:file.name,data:encoded});}
async function openProject(id){const [project,data]=await Promise.all([api('/projects/'+id),api('/dashboard')]);state.project=project;state.page='project';state.data=data;render();window.scrollTo({top:0,behavior:'instant'});}
// One chat bubble. A team proposal shows its answer, or the guardian's buttons while it waits.
function messageHtml(m,guardian){const team=m.role==='admin'||m.is_staff,status={pending:'Aguardando o aceite do responsável',accepted:'Proposta aceita',declined:'Ajuste pedido'};
 return `<div class="message ${team?'team':''} ${m.proposal?'proposal '+m.proposal:''}"><strong>${esc(m.name)} ${team?'· Equipe':''}</strong><small>${date(m.created)}</small>${m.body?`<p>${esc(m.body)}</p>`:''}${Number(m.has_media)?`<a class="message-image" href="/api/message-media/${m.id}" target="_blank" rel="noopener"><img src="/api/message-media/${m.id}" alt="${esc(m.media_name||'Imagem enviada')}" loading="lazy"></a>`:''}${m.proposal?`<div class="proposal-status"><span class="badge">${status[m.proposal]}</span>${m.answer_note?`<p>${esc(m.answer_note)}</p>`:''}${m.proposal==='pending'&&guardian?`<div class="row">${btn('Aceitar proposta','proposal-accept','small',`data-id="${m.id}"`)}${btn('Pedir ajuste','proposal-decline','secondary small',`data-id="${m.id}"`)}</div>`:''}</div>`:''}</div>`;}
function readBase64(file){if(file.size>10*1024*1024)throw new Error('O arquivo deve ter no máximo 10 MB.');return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result.split(',')[1]);reader.onerror=()=>reject(new Error('Não foi possível ler o arquivo.'));reader.readAsDataURL(file);});}
function projectPage(){const p=state.project,admin=operatorUser(),guardian=state.user.role==='guardian'&&p.family_id===state.user.family_id;if(!p)return '';let actions='';if((admin||guardian||(!teamUser()&&p.family_id===state.user.family_id))&&['draft','question','review'].includes(p.status))actions+=btn('Editar ideia','edit-dialog','secondary');if((admin||guardian||(!teamUser()&&p.family_id===state.user.family_id))&&['draft','question'].includes(p.status))actions+=btn(p.status==='draft'?'Enviar para avaliação':'Enviar de volta para avaliação','submit');if(guardian&&p.status==='approval')actions+=btn('Conferir e aprovar orçamento','approve-dialog')+btn('Pedir alteração','revise-dialog','secondary');if(admin&&['review','question','approval','failed'].includes(p.status))actions+=btn('Preparar orçamento','quote-dialog')+(['review','approval'].includes(p.status)?btn('Pedir informação','question-dialog','secondary'):'');if(admin&&p.status==='queued')actions+=btn('Conferir e iniciar impressão','start-dialog');if(admin&&p.status==='printing')actions+=btn('Concluir impressão','finish-dialog')+btn('Registrar falha','fail-dialog','secondary');if((admin||guardian)&&p.status==='ready')actions+=btn('Confirmar retirada','collect-dialog');if(financeUser()&&['ready','completed'].includes(p.status)&&!p.paid&&p.charge>0)actions+=btn('Registrar pagamento','paid-dialog','secondary');if((admin||guardian)&&['draft','review','question','approval','queued'].includes(p.status))actions+=btn('Cancelar pedido','cancel-dialog','secondary');
const q=p.quote,finished=['ready','completed'].includes(p.status),materialCost=finished?Math.round(Math.min(p.actual_grams??p.grams,p.grams)*p.material_rate/1000):q?.materialCost,extraCost=finished?Math.round(Math.max(0,Math.min(p.actual_minutes??p.minutes,p.minutes)-p.used)*p.extra_rate/60):Math.round((p.minutes-p.included)*p.extra_rate/60);return `<button class="text-btn" data-nav="projects">${icon('back')} Voltar aos projetos</button>${header('PROJETO #'+String(p.id).padStart(3,'0'),esc(p.name),esc(explanations[p.status]))}<div class="row section-head">${badge(p.status)}<small>Uma criação de ${esc(p.participant)}</small></div><div class="row section-head">${actions}</div><div class="grid two"><div class="stack">${modelCard(p)}${galleryProjectCard(p)}<div class="card"><h2>${p.kind==='link'?'O pedido':'A ideia'}</h2><p class="preserve">${esc(p.description)}</p><div class="summary"><div><span>Tamanho</span><strong>${esc(p.size)}</strong></div><div><span>Preferência</span><strong>${esc(p.color)} · ${p.quantity} peça(s)</strong></div></div>${p.files.map(f=>`<a class="file" href="/api/files/${f.id}" download>${icon('file')}${esc(f.name)} <small>(${(f.size/1024).toFixed(0)} KB)</small></a>`).join('')}${['draft','question','review'].includes(p.status)?`<form id="file-form" class="stack section"><label>Adicionar arquivo<input name="attachment" type="file" accept="${p.kind==='file'?'.stl,.3mf':'.stl,.3mf,.png,.jpg,.jpeg'}" required><span class="field-help">Até cinco arquivos de 10 MB. Envie apenas modelos e imagens de referência.</span></label><button class="btn secondary" type="submit">Enviar arquivo</button></form>`:''}</div>${q?`<div class="card"><div class="section-head"><h2>${['ready','completed'].includes(p.status)?'Consumo final':'Orçamento do projeto'}</h2>${icon('clock')}</div><p class="preserve">${esc(p.quote_note)}</p><div class="summary"><div><span>Tempo estimado total</span><strong>${hours(p.minutes)}</strong></div><div><span>Material estimado total</span><strong>${p.grams} g de ${esc(p.material)}</strong></div><div><span>${p.status==='approval'?'Uso previsto da cota':'Horas da cota reservadas na aprovação'}</span><strong>${hours(p.status==='approval'?q.included:p.included)}</strong></div><div><span>Material (${money(p.material_rate)}/kg)</span><strong>${money(materialCost)}</strong></div><div><span>Horas extras</span><strong>${money(p.status==='approval'?q.extraCost:extraCost)}</strong></div><div class="total"><span>${['ready','completed'].includes(p.status)?'Valor final adicional':'Máximo adicional'}</span><strong>${money(p.status==='approval'?q.total:p.charge)}</strong></div>${['ready','completed'].includes(p.status)?`<div><span>Consumo real registrado</span><strong>${hours(p.actual_minutes)} · ${p.actual_grams} g</strong></div><div><span>Débito na cota</span><strong>${hours(p.used)}</strong></div><div><span>Pagamento</span><strong>${p.paid?'Registrado':p.charge?'A combinar com a equipe':'Sem valor adicional'}</strong></div>`:''}</div><small>${p.status==='approval'?'O saldo é conferido novamente ao aprovar. Não haverá impressão sem aprovação.':'O custo é limitado ao valor aprovado. A parcela não utilizada da reserva é liberada.'}</small></div>`:''}<div class="card"><h2>Conversa com a equipe</h2><p>Uma dúvida ou uma ideia nova? Conte por aqui.</p>${p.messages.length?p.messages.map(m=>messageHtml(m,guardian)).join(''):'<p class="muted">As orientações sobre este projeto aparecerão aqui.</p>'}<form id="message-form" class="stack"><label>Sua mensagem<textarea name="body" maxlength="3000" placeholder="${admin?'Escreva para a família. Ex.: encontramos este modelo, serve para você?':'Escreva sua dúvida ou orientação…'}"></textarea></label><label>Imagem (opcional)<input name="image" type="file" accept="image/jpeg,image/png,image/webp"><span class="field-help">JPG, PNG ou WebP de até 10 MB.</span></label>${admin&&['review','question','approval'].includes(p.status)?'<label class="check"><input type="checkbox" name="proposal">Pedir o aceite do responsável (ex.: um modelo sugerido)</label>':''}${admin?'<p class="field-help">O responsável principal recebe um aviso no WhatsApp com a mensagem e a imagem.</p>':''}<button class="btn secondary" type="submit">Enviar mensagem ${icon('arrow')}</button></form></div></div><aside><div class="card"><h2>O caminho da sua criação</h2><ol class="timeline">${p.events.map(e=>`<li>${esc(e.text)}<small>${new Date(e.created).toLocaleString('pt-BR')}</small></li>`).join('')}</ol></div><div class="notice section">${icon('help')}<div><h3>Aprender também é experimentar</h3><p>A impressão é feita por um responsável. Você acompanha, pergunta e aprende em cada etapa.</p></div></div></aside></div>`;}
function queuePage(){const q=state.data.queue;return `${header('CADA IDEIA TEM SUA VEZ',teamUser()?'Produção do clube':'Fila do clube','Acompanhe o caminho das criações, uma camada de cada vez.')}<div class="notice">${icon('clock')}<div><h3>${q.some(p=>p.status==='printing')?'Uma criação está sendo impressa':'Nenhuma impressão em andamento'}</h3><p>Atualização manual pela equipe. O tempo é uma estimativa de impressão, não uma promessa de entrega.</p></div></div><div class="card section">${q.length?q.map(p=>`<div class="queue-item"><span class="queue-index">${p.position}</span><div><h3>${p.name?esc(p.name):'Pedido #'+String(p.id).padStart(3,'0')}</h3><p>${hours(p.minutes)} estimadas ${p.own?'· Da sua família':''}</p></div>${badge(p.status)}${p.own||teamUser()?`<button data-project="${p.id}" aria-label="Abrir projeto">${icon('arrow')}</button>`:''}</div>`).join(''):empty('A próxima criação pode ser a sua','Quando um orçamento for aprovado, o projeto aparecerá nesta fila.')}</div><div class="card section"><h2>Uma fila justa e fácil de entender</h2><p>Os projetos entram por ordem de aprovação do orçamento. Pausas de manutenção podem alterar a previsão, mas a ordem permanece. Informações de outras famílias ficam protegidas.</p><button class="text-btn" data-action="rules">Ver regras de participação ${icon('arrow')}</button></div>`;}
function balancePage(){const d=state.data,f=d.family,ps=d.projects.filter(p=>p.family_id===f.id&&['ready','completed'].includes(p.status));return `${header('TRANSPARÊNCIA EM CADA CRIAÇÃO','Minha cota','Seu tempo, seus projetos e seus custos, sem surpresas.',btn('Baixar extrato do mês','export-usage','secondary'))}<div class="grid two"><div class="stack"><div class="card"><div class="eyebrow">SEU PLANO</div><h2>${f.plan==='annual'?'Cota anual':'Cota mensal'} · ${esc(f.name)}</h2><p>Franquia de ${hours(f.allowance)} por mês. Período atual: ${d.balance.period.split('-').reverse().join('/')}.</p><div class="summary"><div><span>Preço de referência atual</span><strong>${money(f.plan==='annual'?d.config.annual:d.config.monthly)} / ${f.plan==='annual'?'ano':'mês'}</strong></div><div><span>Hora extra</span><strong>${money(d.config.extra)} / hora</strong></div><div><span>Filamento</span><strong>Custo + ${d.config.markup}%</strong></div></div><small>Mensalidades e anuidades são combinadas com a equipe e registradas manualmente. O portal não realiza débitos automáticos.</small></div><div class="notice">${icon('help')}<div><h3>O que são horas reservadas?</h3><p>São horas destinadas aos projetos que você aprovou e ainda não terminaram. Elas ficam vinculadas ao mês da aprovação.</p></div></div></div>${balanceCard()}</div><div class="section"><h2>Histórico dos projetos</h2>${ps.length?`<div class="card table-wrap"><table><thead><tr><th>Projeto</th><th>Mês da cota</th><th>Horas usadas</th><th>Valor adicional</th><th>Pagamento</th></tr></thead><tbody>${ps.map(p=>`<tr><td><button class="text-btn" data-project="${p.id}">${esc(p.name)}</button></td><td>${p.period}</td><td>${hours(p.used)}</td><td>${money(p.charge)}</td><td>${p.paid?'Registrado':p.charge?'Pendente':'Sem cobrança'}</td></tr>`).join('')}</tbody></table></div>`:empty('Seu histórico começa na primeira criação','Os custos e as horas utilizadas aparecem aqui quando a impressão é concluída.')}</div><div class="card section"><h2>Pagamentos da participação</h2>${d.payments.length?d.payments.map(p=>`<div class="summary"><div><span>${esc(p.description)} · ${date(p.created)}</span><strong>${money(p.cents)}</strong></div></div>`).join(''):'<p>Nenhum pagamento registrado pela equipe.</p>'}<button class="text-btn" data-action="rules">Entender todas as regras ${icon('arrow')}</button></div>`;}
const lessons=[
{title:'Como uma ideia vira um objeto?',time:2,body:'Uma impressora 3D constrói objetos em camadas bem fininhas. Pense em várias folhas empilhadas: aos poucos, elas formam uma altura. A impressora faz algo parecido, depositando material conforme um desenho digital.',extra:'O caminho é: ideia → modelo 3D → preparação → orçamento → impressão → teste. Você pode começar só com um desenho no papel. A equipe ajuda no próximo passo.',activity:'Observe um objeto da sua casa. Se ele fosse construído em camadas, qual parte seria a primeira?'},
{title:'Do desenho ao modelo 3D',time:3,body:'Um desenho mostra a sua ideia. Um modelo 3D descreve a largura, a altura e a profundidade do objeto no computador. Comece com formas simples: caixas, cilindros e esferas podem formar criações incríveis.',extra:'Ainda não sabe modelar? Envie um desenho ou explique o que quer criar. A equipe vai orientar o caminho. Modelos encontrados na internet também precisam ter permissão de uso.',activity:'Desenhe uma peça útil e anote três medidas. Pode ser um porta-lápis ou um suporte para um brinquedo.'},
{title:'O que são STL e 3MF?',time:2,body:'STL e 3MF são tipos de arquivo usados para guardar modelos 3D. O STL descreve principalmente a forma da peça. O 3MF pode guardar outras informações, como cores e organização dos objetos.',extra:'Enviar um arquivo não significa que ele já está pronto para imprimir. A equipe verifica dimensões, espessura e possíveis problemas antes do orçamento.',activity:'Ao enviar um modelo, escreva a medida esperada. Isso ajuda a equipe a conferir se o tamanho está correto.'},
{title:'Preparar o arquivo: o fatiamento',time:3,body:'Fatiar é transformar o modelo em instruções para a impressora. Um programa calcula as camadas, os movimentos e o material necessário. Essa preparação é feita pela equipe do clube.',extra:'Algumas peças precisam de suportes temporários para sustentar partes no ar. Eles também consomem material e serão considerados no orçamento, assim como eventuais trocas de cor.',activity:'Imagine imprimir a letra T em pé. Como sustentar as pontas da parte de cima? Converse com a equipe sobre os suportes.'},
{title:'Como entender o orçamento',time:3,body:'O custo depende do tempo da máquina e do material usado. Sua cota inclui horas mensais, mas o filamento é cobrado à parte. Quando a franquia termina, horas extras só entram com aprovação.',extra:'O orçamento mostra a estimativa total para todas as peças do pedido, incluindo suportes e perdas previstas. O valor final pode diminuir, mas nunca ultrapassa o aprovado. Uma falha da máquina não gera cobrança.',activity:'Compare duas versões da mesma ideia: uma pequena e outra maior. Qual deve consumir mais material? O aumento nem sempre é proporcional à altura.'},
{title:'Testar, aprender e melhorar',time:2,body:'A primeira versão é uma oportunidade de aprender. Uma tampa pode ficar apertada ou um suporte pode precisar de outra forma. Teste com cuidado, observe e anote o que mudaria.',extra:'Cada melhoria é um novo projeto ou uma nova avaliação. Converse com a equipe antes de repetir uma impressão. O orçamento da nova versão precisa de aprovação.',activity:'Depois de receber sua peça, anote: o que funcionou, o que pode melhorar e o que você aprendeu.'},
{title:'Cuidados no espaço maker',time:2,body:'A impressora possui partes quentes e partes que se movimentam. Observe com orientação e nunca toque na máquina em funcionamento. O início de cada impressão depende da conferência de um responsável.',extra:'Crianças participam com acompanhamento adequado. Não coloque peças pequenas na boca. Peças impressas não devem ser usadas para alimentos, eletricidade ou suportar pessoas sem avaliação técnica específica.',activity:'Antes da primeira visita, combine com o responsável: onde observar, quando perguntar e quem pode tocar no equipamento.'}
];
function learnPage(){return `${header('CURIOSIDADE É O PRIMEIRO PASSO','Aprender fazendo.','Pequenas descobertas para dar vida às suas ideias.')}<div class="grid three">${lessons.map((l,i)=>`<button class="choice" data-lesson="${i}"><div class="eyebrow">DESCOBERTA 0${i+1} · ${l.time} MIN</div>${icon(['cube','pencil','file','queue','clock','spark','help'][i])}<strong>${l.title}</strong><p>Uma explicação simples e uma atividade para experimentar.</p><span class="text-btn">Vamos descobrir ${icon('arrow')}</span></button>`).join('')}</div>${makerGuide()}`;}
const guideLinks=[['Modelos gratuitos',[['MakerWorld','https://makerworld.com','Da Bambu Lab, imprime com um clique'],['Printables','https://www.printables.com','Curadoria e fotos reais'],['Thingiverse','https://www.thingiverse.com','O maior acervo'],['Thangs','https://thangs.com','Busca em vários sites'],['Cults3D','https://cults3d.com','Decoração e miniaturas, grátis e pagos']]],['Criar e editar',[['Tinkercad','https://www.tinkercad.com','Comece por aqui, no navegador'],['Autodesk Fusion','https://www.autodesk.com/products/fusion-360/personal','Peças técnicas, grátis para hobby'],['Onshape','https://www.onshape.com','CAD no navegador'],['FreeCAD','https://www.freecad.org','Engenharia, código aberto'],['Blender','https://www.blender.org','Escultura e personagens']]],['Fatiar',[['Bambu Studio','https://bambulab.com/en/download/studio','Fatiador oficial da Bambu Lab'],['OrcaSlicer','https://github.com/SoftFever/OrcaSlicer/releases','Calibração fina de filamentos']]]];
function makerGuide(){return `<section class="section card stack maker-guide"><div class="row spread"><div><div class="eyebrow">GUIA DO MAKER</div><h2>Arquivos, modelos e programas</h2><p class="muted">Envie seus projetos em <b>.3mf</b> (recomendado) ou <b>.stl</b>. Tem um .step, .obj ou .svg? Importe no Bambu Studio e salve como .3mf antes de enviar.</p></div><div class="row"><a class="btn secondary small" href="/guia-impressao-3d.html" target="_blank" rel="noopener">${icon('file')} Abrir guia completo</a><a class="btn small" href="/guia-impressao-3d.html" download="Guia-do-Maker-Clube-Maker-3D.html">Baixar HTML</a></div></div><div class="grid three">${guideLinks.map(([title,links])=>`<div><h3>${title}</h3><ul class="guide-links">${links.map(([name,url,note])=>`<li><a href="${url}" target="_blank" rel="noopener noreferrer">${name}</a><small>${note}</small></li>`).join('')}</ul></div>`).join('')}</div><p class="muted"><small>Baixe programas sempre pelo site oficial. Crianças devem criar contas nesses sites junto com o responsável.</small></p></section>`;}
function lessonModal(i){const l=lessons[i];modal(`<span class="eyebrow">DESCOBERTA 0${i+1}</span>`, `<article class="lesson"><h3>${l.title}</h3><p>${l.body}</p><p>${l.extra}</p><div class="activity"><strong>Agora é com você</strong><p>${l.activity}</p></div><div class="section">${btn('Entendi!','close')}</div></article>`);}
function familiesPage(){const fs=state.data.families;return `${header('CRIANDO JUNTOS','Famílias do clube',`${fs.length} de 10 cotas do piloto ocupadas.`,btn(icon('plus')+' Nova família','family-new'))}${fs.length?`<div class="grid two">${fs.map(f=>`<div class="card"><div class="row spread"><h2>${esc(f.name)}</h2><span class="badge">${f.plan==='annual'?'Anual':'Mensal'}</span></div><p>${hours(f.balance.available)} disponíveis · ${hours(f.balance.held)} reservadas</p>${f.members.length?f.members.map(m=>`<p><strong>${esc(m.name)}</strong><br><small>${esc(m.email)} · ${m.role==='guardian'?'Responsável':'Aprendiz'}</small></p>`).join(''):'<p>Aguardando o primeiro responsável aceitar o convite.</p>'}<div class="row">${btn('Gerar convite','invite-dialog','secondary small',`data-id="${f.id}"`)}${btn('Registrar mensalidade / anuidade','payment-dialog','secondary small',`data-id="${f.id}"`)}</div></div>`).join('')}</div>`:empty('O clube começa com as famílias','Cadastre a primeira família e gere um convite para o responsável.',btn('Cadastrar primeira família','family-new'))}`;}
function settingsPage(){const c=state.data.config;return `${header('DO JEITO DO SEU CLUBE','Configurações','Valores editáveis, com respeito aos orçamentos já aprovados.')}<form id="settings-form" class="stack"><div class="card"><h2>Participação e horas</h2><div class="form-grid"><label>Mensalidade (R$)<input name="monthly" type="number" min="0" max="10000" step="0.01" required value="${c.monthly/100}"></label><label>Anuidade (R$)<input name="annual" type="number" min="0" max="100000" step="0.01" required value="${c.annual/100}"></label><label>Horas mensais para novas famílias<input name="hours" type="number" min="1" max="100" step="0.5" required value="${c.hours}"></label><label>Hora extra (R$)<input name="extra" type="number" min="0" max="1000" step="0.01" required value="${c.extra/100}"></label><label>Acréscimo sobre o filamento (%)<input name="markup" type="number" min="0" max="200" required value="${c.markup}"></label></div><p class="section">Alterações valem para novos orçamentos. A franquia de famílias já cadastradas é preservada.</p></div><div class="card"><div class="section-head"><h2>Materiais disponíveis</h2>${btn(icon('plus')+' Material','material-add','secondary small')}</div><div id="materials">${c.materials.map((m,i)=>materialFields(m,i)).join('')}</div><small>O custo por kg deve ser o custo de compra. O acréscimo é aplicado automaticamente no orçamento. Desative materiais que não estão disponíveis.</small></div><div class="error" role="alert"></div><div><button type="submit" class="btn">Salvar configurações ${icon('check')}</button></div></form><div class="card section"><h2>Regras iniciais do piloto</h2>${rulesHtml()}</div>`;}
function materialFields(m,i){return `<div class="settings-material" data-material="${i}"><div class="form-grid"><label>Nome<input data-key="name" value="${esc(m.name)}" required maxlength="40"></label><label>Custo por kg (R$)<input data-key="cost" type="number" min="0.01" max="10000" step="0.01" value="${m.cost/100}" required></label><label>Cores, separadas por vírgula<input data-key="colors" value="${esc(m.colors.join(', '))}" required></label><label class="check"><input data-key="active" type="checkbox" ${m.active?'checked':''}>Disponível para novos pedidos</label></div></div>`;}
function rulesHtml(){return `<ol class="rule-list"><li><strong>Horas mensais, sem acúmulo</strong>A franquia renova no primeiro dia de cada mês, no horário de Brasília. Horas não reservadas expiram.</li><li><strong>Reserva na aprovação</strong>Um projeto aprovado reserva horas do mês da aprovação, mesmo se for produzido depois. Cancelamentos liberam a reserva no mês de origem.</li><li><strong>O orçamento é o teto</strong>Tempo e material abaixo da estimativa reduzem o consumo e o valor. Excedentes são absorvidos pelo clube. Alterar o projeto exige nova avaliação.</li><li><strong>Falhas da máquina são do clube</strong>A tentativa que falhou não consome a cota nem gera cobrança. Uma nova tentativa passa por orçamento e aprovação.</li><li><strong>Ordem de aprovação</strong>Sem prioridade paga ou ultrapassagens no piloto. A equipe informa pausas de manutenção.</li><li><strong>Cancelamento gratuito antes de imprimir</strong>Até começar a impressão, a reserva é liberada sem cobrança. Depois disso, o atendimento é feito pela equipe, sem cancelamento automático.</li><li><strong>Somente materiais disponíveis</strong>A equipe mantém os materiais e as cores atualizados e inclui suportes e perdas previstas nas estimativas.</li><li><strong>Valores iniciais e aprovação do responsável</strong>Referência inicial: R$ 150/mês ou R$ 1.500/ano, 12 h/mês, R$ 6/h extra e filamento a custo + 20%. Valores atuais aparecem na cota. Apenas responsáveis podem aprovar orçamentos.</li></ol>`;}
function projectModal(action){const p=state.project;switch(action){case'license-dialog':modal('Licença do modelo',`<p>Abra a peça no site original e confira a licença de <strong>${esc(p.model.title)}</strong>.</p>${licenseChip(p.model.license,p.model.license_level)}<form id="license-form" class="stack section"><label class="check"><input name="checked" type="checkbox" required>Conferi a licença e a impressão desta peça é permitida para o clube.</label><button type="submit" class="btn">Registrar conferência</button></form>`);break;case'edit-dialog':modal('Ajustar sua ideia',`<form id="edit-form" class="stack"><label>Nome<input name="name" value="${esc(p.name)}" required maxlength="100"></label><label>Descrição<textarea name="description" required maxlength="3000">${esc(p.description)}</textarea></label><label>Participante<input name="participant" value="${esc(p.participant)}" required maxlength="80"></label><label>Tamanho<input name="size" value="${esc(p.size)}" required maxlength="100"></label><label>Cor<select name="color">${['Quero ajuda',...new Set(state.data.config.materials.filter(m=>m.active).flatMap(m=>m.colors))].map(c=>`<option ${c===p.color?'selected':''}>${esc(c)}</option>`).join('')}</select></label><label>Quantidade<input name="quantity" type="number" min="1" max="50" required value="${p.quantity}"></label><button type="submit" class="btn">Salvar alterações</button></form>`);break;case'approve-dialog':{const q=p.quote;modal('Vamos dar forma à sua ideia?',`<p>Você autoriza a produção de <strong>${esc(p.name)}</strong> conforme o orçamento.</p><div class="summary"><div><span>Horas reservadas</span><strong>${hours(q.included)}</strong></div><div class="total"><span>Máximo adicional</span><strong>${money(q.total)}</strong></div></div><form id="approve-form" class="stack section"><label class="check"><input name="confirm" type="checkbox" required>Sou responsável pela família e aprovo o orçamento. Entendo que material e horas extras são cobrados à parte.</label><button type="submit" class="btn">Aprovar e entrar na fila</button></form>`);break;}
case'quote-dialog':modal('Preparar orçamento',`<p>Informe os totais de todas as peças, incluindo suportes e perdas previstas no fatiamento.</p><form id="quote-form" class="stack"><div class="form-grid"><label>Tempo total (minutos)<input name="minutes" type="number" min="1" max="10000" required value="${p.minutes||''}"></label><label>Material total (gramas)<input name="grams" type="number" min="0.1" max="10000" step="0.1" required value="${p.grams||''}"></label></div><label>Material<select name="material">${state.data.config.materials.filter(m=>m.active).map(m=>`<option ${p.material===m.name?'selected':''}>${esc(m.name)}</option>`).join('')}</select></label><label>Explique a proposta à família<textarea name="note" required maxlength="1000" placeholder="Informe a cor acordada, dimensões e orientações.">${esc(p.quote_note)}</textarea></label><button class="btn" type="submit">Enviar orçamento para aprovação</button></form>`);break;
case'finish-dialog':modal('Uma criação pronta!',`<p>Registre o consumo real. O sistema aplica automaticamente o limite do orçamento aprovado.</p><form id="finish-form" class="stack"><label>Tempo real total (minutos)<input name="minutes" type="number" min="1" max="10000" required value="${p.minutes}"></label><label>Material real total (gramas)<input name="grams" type="number" min="0.1" max="10000" step="0.1" required value="${p.grams}"></label><button class="btn" type="submit">Marcar como pronto para retirar</button></form>`);break;
case'start-dialog':modal('Conferência antes de imprimir',`<p>Verifique a mesa, o material, o arquivo preparado e as condições de segurança. Inicie no equipamento antes de atualizar o portal.</p><form id="start-form" class="stack"><label class="check"><input type="checkbox" name="checked" required>Conferi a máquina e iniciei esta impressão no equipamento.</label><button class="btn" type="submit">Registrar início da impressão</button></form>`);break;
case'question-dialog':modal('O que precisamos saber?',`<form id="question-form" class="stack"><label>Pergunta para a família<textarea name="note" required maxlength="1000" placeholder="Explique de forma simples o que falta definir."></textarea></label><button type="submit" class="btn">Enviar pergunta</button></form>`);break;
case'fail-dialog':modal('Registrar impressão interrompida',`<p>Esta tentativa não será cobrada. As horas serão liberadas e uma nova tentativa exigirá novo orçamento.</p><form id="fail-form" class="stack"><label>O que aconteceu?<textarea name="reason" required maxlength="1000"></textarea></label><button type="submit" class="btn danger">Registrar falha sem cobrança</button></form>`);break;
case'revise-dialog':modal('Pedir uma alteração',`<form id="revise-form" class="stack"><label>O que você gostaria de mudar?<textarea name="body" required maxlength="3000"></textarea></label><button type="submit" class="btn">Enviar para nova avaliação</button></form>`);break;
default:{const map={'cancel-dialog':['Cancelar este pedido?','A reserva de horas será liberada no mês de origem. Não haverá cobrança.','cancel','Cancelar pedido'],'collect-dialog':['Sua criação já está com você?','Confirme somente depois de receber a peça.','collect','Sim, a peça foi retirada'],'paid-dialog':['Registrar pagamento recebido?','Confirme somente depois de verificar o recebimento do valor final de '+money(p.charge)+'.','paid','Confirmar recebimento']};const c=map[action];if(c)modal(c[0],`<p>${c[1]}</p><div class="row">${btn('Voltar','close','secondary')}${btn(c[3],'confirmed','',`data-operation="${c[2]}"`)}</div>`);}
}}
async function act(action,target){if(await featureAction(action,target))return;switch(action){case'new':newWizard();return;case'close':close();return;case'logout':close();await api('/logout',{});state.page='home';await boot();return;case'open':await openProject(target.dataset.id);return;case'help':modal('Da ideia à sua criação',`<div class="lesson"><p><strong>1. Imagine.</strong> Conte sua ideia ou envie um arquivo. Não precisa ter experiência.</p><p><strong>2. Combine.</strong> A equipe orienta e prepara o orçamento. O responsável decide se quer aprovar.</p><p><strong>3. Acompanhe.</strong> Seu projeto entra na fila e é produzido com supervisão.</p><p><strong>4. Descubra.</strong> Retire a peça, teste e pense no que gostaria de melhorar!</p><div class="notice"><div><h3>Precisa de ajuda?</h3><p>Use a conversa dentro do projeto ou fale com a equipe na Emersol, em Itumbiara.</p></div></div></div>`);return;case'rules':modal('Regras do piloto',rulesHtml());return;case'account':modal('Seu espaço no clube',`<p><strong>${esc(state.user.name)}</strong><br>${esc(state.user.email)}</p>${state.user.role==='guardian'?`<h3>Participantes da família</h3><p>${state.data.participants.map(p=>esc(p.name)).join(', ')||'Nenhum participante adicionado.'}</p><form id="participant-form" class="stack"><label>Nome do participante<input name="name" required maxlength="80" placeholder="Ex.: Ana"></label><button type="submit" class="btn secondary">Adicionar participante</button></form><p class="section"><small>Perfis identificam os criadores. Para acesso próprio de um aprendiz, peça um convite à equipe. Ele não poderá aprovar custos.</small></p>`:''}<div class="section">${btn('Sair da conta','logout','secondary')}</div>`);return;case'wizard-back':captureWizard();state.wizard.step--;render();return;case'wizard-exit':state.wizard=null;state.page='home';render();return;case'draft':await saveWizard(false);return;case'submit':await api(`/projects/${state.project.id}/submit`,{});toast('Enviado para avaliação!');await openProject(state.project.id);return;case'confirmed':await api(`/projects/${state.project.id}/${target.dataset.operation}`,{});close();toast('Atualização registrada.');await openProject(state.project.id);return;
case'family-new':modal('Uma nova família no clube',`<form id="family-form" class="stack"><label>Nome da família<input name="name" required maxlength="80" placeholder="Ex.: Família Oliveira"></label><label>Plano<select name="plan"><option value="monthly">Mensal · ${money(state.data.config.monthly)}</option><option value="annual">Anual · ${money(state.data.config.annual)}</option></select></label><small>Franquia inicial: ${state.data.config.hours} horas por mês. Depois do cadastro, gere um convite para o responsável.</small><button type="submit" class="btn">Cadastrar família</button></form>`);return;
case'invite-dialog':modal('Convidar para o clube',`<p>O convite vale por sete dias e pode ser usado uma vez. Entregue o link à pessoa certa.</p><form id="invite-form" data-id="${target.dataset.id}" class="stack"><label>Tipo de acesso<select name="role"><option value="guardian">Responsável — pode aprovar orçamentos</option><option value="learner">Aprendiz — pode criar, sem aprovar custos</option></select></label><button class="btn" type="submit">Gerar link de convite</button></form>`);return;

case'material-add':$('#materials').insertAdjacentHTML('beforeend',materialFields({name:'',cost:10000,colors:[],active:true},Date.now()));return;
case'copy-invite':{const input=$('#invite-link');try{await navigator.clipboard.writeText(input.value);toast('Link copiado.');}catch{input.select();toast('Selecione e copie o link.');}return;}
case'link-preview':await previewLink();return;
case'proposal-accept':await api(`/projects/${state.project.id}/answer`,{messageId:Number(target.dataset.id),accept:true});toast('Proposta aceita. A equipe vai preparar o orçamento.');await openProject(state.project.id);return;
case'proposal-decline':modal('O que você gostaria de ajustar?',`<form id="decline-form" class="stack" data-id="${target.dataset.id}"><label>Conte para a equipe<textarea name="note" required maxlength="1000" placeholder="Ex.: prefiro um modelo mais baixo, com espaço para borracha."></textarea></label><button type="submit" class="btn">Enviar pedido de ajuste</button></form>`);return;
default:if(action.endsWith('-dialog'))projectModal(action);
}}
async function submit(form){if(await featureSubmit(form))return;const fd=new FormData(form),obj=Object.fromEntries(fd);switch(form.id){case'auth-form':{if(obj.photo?.size>2*1024*1024)throw new Error('A foto deve ter até 2 MB.');await api('/'+form.dataset.mode,{...obj,token:new URLSearchParams(location.search).get('convite')});history.replaceState(null,'','/');if(obj.photo?.size){try{await api('/profile/photo',await encodedFile(obj.photo,2));}catch{toast('Conta criada. Adicione sua foto em Meu perfil.');}}await boot();return;}
case'wizard-form':captureWizard();if(state.wizard.step===1&&state.wizard.kind==='file'&&!state.wizard.file)throw new Error('Selecione seu arquivo STL ou 3MF.');if(state.wizard.step===1&&state.wizard.kind==='link'){const w=state.wizard;if(w.link?.input!==w.url.trim())await previewLink();if(!w.linkTitle.trim())throw new Error('Escreva o nome da peça para continuar.');w.name=w.linkTitle.trim().slice(0,100);}if(state.wizard.step===3)await saveWizard(true);else{state.wizard.step++;render();}return;
case'message-form':{const image=fd.get('image');const media=image&&image.size?{name:image.name,data:await readBase64(image)}:null;if(!obj.body?.trim()&&!media)throw new Error('Escreva a mensagem ou escolha uma imagem.');await api(`/projects/${state.project.id}/message`,{body:obj.body||'',media,proposal:fd.get('proposal')==='on'});toast(fd.get('proposal')==='on'?'Proposta enviada ao responsável.':'Mensagem enviada.');await openProject(state.project.id);return;}
case'decline-form':await api(`/projects/${state.project.id}/answer`,{messageId:Number(form.dataset.id),accept:false,note:obj.note});close();toast('Pedido de ajuste enviado.');await openProject(state.project.id);return;
case'file-form':await upload(state.project.id,fd.get('attachment'));toast('Arquivo enviado.');await openProject(state.project.id);return;
case'edit-form':await api(`/projects/${state.project.id}/edit`,{...obj,quantity:Number(obj.quantity)});break;
case'approve-form':await api(`/projects/${state.project.id}/approve`,{total:state.project.quote.total,included:state.project.quote.included});break;
case'quote-form':await api(`/projects/${state.project.id}/quote`,{...obj,minutes:Number(obj.minutes),grams:Number(obj.grams)});break;
case'finish-form':await api(`/projects/${state.project.id}/finish`,{minutes:Number(obj.minutes),grams:Number(obj.grams)});break;
case'start-form':await api(`/projects/${state.project.id}/start`,{checked:fd.has('checked')});break;
case'license-form':await api(`/projects/${state.project.id}/license`,{checked:fd.has('checked')});break;
case'question-form':await api(`/projects/${state.project.id}/question`,obj);break;
case'fail-form':await api(`/projects/${state.project.id}/fail`,obj);break;
case'revise-form':await api(`/projects/${state.project.id}/revise`,{});await api(`/projects/${state.project.id}/message`,obj);break;
case'participant-form':await api('/participants',obj);close();toast('Participante adicionado.');await refresh();return;
case'family-form':await api('/families',obj);close();state.page='families';toast('Família cadastrada. Agora gere um convite.');await refresh();return;
case'invite-form':{const r=await api('/invites',{familyId:Number(form.dataset.id),role:obj.role});modal('Convite pronto',`<p>Entregue este link à pessoa convidada. Ele expira em sete dias.</p><label>Link de acesso<input id="invite-link" readonly value="${esc(location.origin+'/?convite='+r.token)}"></label><div class="section">${btn('Copiar convite','copy-invite')}</div><p><small>Em execução local, o convite só funciona onde o servidor estiver acessível.</small></p>`);return;}

case'settings-form':{const materials=[...form.querySelectorAll('[data-material]')].map(el=>({name:$('[data-key=name]',el).value,cost:Math.round(Number($('[data-key=cost]',el).value)*100),colors:$('[data-key=colors]',el).value.split(',').map(s=>s.trim()).filter(Boolean),active:$('[data-key=active]',el).checked}));await api('/settings',{monthly:Math.round(Number(obj.monthly)*100),annual:Math.round(Number(obj.annual)*100),hours:Number(obj.hours),extra:Math.round(Number(obj.extra)*100),markup:Number(obj.markup),materials});toast('Configurações salvas.');await refresh();return;}
default:return;}
close();toast('Atualização registrada com sucesso.');await openProject(state.project.id);}
document.addEventListener('click',async e=>{const target=e.target.closest('button');if(!target||(target.type==='submit'&&target.form&&!target.dataset.action)||busy)return;try{busy=true;if(target.dataset.nav){close();if(state.wizard&&state.page==='new'){captureWizard();}state.page=target.dataset.nav;await refresh({navigate:true});$('#main').focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});}else if(target.dataset.project)await openProject(target.dataset.project);else if(target.dataset.filter){state.filter=target.dataset.filter;render();}else if(target.dataset.kind){state.wizard.kind=target.dataset.kind;state.wizard.file=null;state.wizard.size=target.dataset.kind==='link'?'Como no modelo original':'Quero ajuda';render();}else if(target.dataset.lesson!==undefined)lessonModal(Number(target.dataset.lesson));else if(target.dataset.action)await act(target.dataset.action,target);}catch(e){error(e);}finally{busy=false;}});
document.addEventListener('submit',async e=>{e.preventDefault();if(busy)return;busy=true;const form=e.target,button=$('button[type=submit]',form);if(button)button.disabled=true;try{await submit(form);}catch(e){error(e);}finally{busy=false;if(button)button.disabled=false;}});
document.addEventListener('paste',e=>{if(e.target.name!=='url'||e.target.form?.id!=='wizard-form')return;setTimeout(async()=>{if(busy)return;busy=true;try{await previewLink();}catch(err){error(err);}finally{busy=false;}},0);});
window.addEventListener('beforeunload',e=>{if(state.page==='new'&&state.wizard){e.preventDefault();e.returnValue='';}});
boot().catch(e=>{$('#app').innerHTML=`<main class="auth-form"><div><h1>Não conseguimos abrir o clube.</h1><p>${esc(e.message)}</p><p>Confira se o servidor está em execução e recarregue a página.</p></div></main>`;});
